/* No falling, disappearing, slash or hit reaction; celebrate everybody. */
.fx-slash,.fx-impact,.fx-shard,.fx-projectile{display:none!important}
.fx-receiving{animation:none!important;filter:drop-shadow(0 0 8px #ffe7ac)}
.battle-fx-layer:after{content:'✦';position:absolute;left:var(--x,48%);top:32%;font-size:48px;color:#ffeb9b;text-shadow:0 0 18px #ffe8a2;animation:friendly-spark .6s ease-out both}
.challenge-applause{text-align:center;font-weight:bold;padding:12px 16px;border:2px solid #cda85d;border-radius:14px;background:#fff4cd;color:#594322;line-height:1.6}
.challenge-finished .pve-actor,.challenge-finished .fighter{opacity:1!important;visibility:visible!important}
.challenge-finished .pve-sprite,.challenge-finished .character-pick{animation:friendly-bow 1.8s ease-in-out 2!important;transform-origin:50% 100%}
.pve-team.enemy .pve-sprite img{filter:none!important}.pve-team.enemy .pve-sprite{opacity:1!important;filter:none!important}
.pve-strike-burst{background:none!important;width:36px!important;height:36px!important;border-radius:50%;border:2px solid #ffea9a;box-shadow:0 0 14px #ffecad}
.pve-hp.enemy .pve-meter:not(.mp)>i{background:linear-gradient(90deg,#f4b85d,#ffe396)!important}
.pve-outcome{font-size:clamp(17px,4.5vw,30px)!important;max-width:86%;text-align:center;line-height:1.5}
.status-bar-row{grid-template-columns:48px 1fr 88px}
.victory-banner strong{font-size:clamp(16px,4vw,27px)!important;letter-spacing:0!important}
@keyframes friendly-spark{from{opacity:0;transform:scale(.5)}40%{opacity:1}to{opacity:0;transform:translateY(-20px) scale(1.2)}}
@keyframes friendly-bow{0%,100%{rotate:0deg}35%{rotate:4deg}65%{rotate:-3deg}}
@media(prefers-reduced-motion:reduce){.challenge-finished .pve-sprite,.challenge-finished .character-pick,.battle-fx-layer:after{animation:none!important}}

/* Keep long action labels inside each command at every viewport size. */
.character-command{box-sizing:border-box;width:384px;min-width:0;max-width:calc(100% - 16px)}
.character-command header{min-width:0}
.character-command header strong{min-width:0;overflow-wrap:anywhere}
.character-command .command-row{min-width:0;grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch}
.character-command .command-row button,
.character-command .command-row button.selected{box-sizing:border-box;min-width:0;max-width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;padding:8px 5px;min-height:68px;white-space:normal;line-height:1.4;text-align:center}
.character-command .command-row button strong{display:block;min-width:0;max-width:100%;font:inherit;font-weight:700;white-space:normal;overflow-wrap:anywhere;word-break:normal;line-height:1.4}
.character-command .command-row button .icon{display:block;flex:0 0 auto;margin:0}
.character-command .command-decision{min-width:0;flex-wrap:wrap}
.character-command .command-decision>span,
.character-command .command-decision small{min-width:0;max-width:100%;white-space:normal;overflow-wrap:anywhere}

